"""Task-local inspection: show the schema of the existing SQLite database."""

import sqlite3

conn = sqlite3.connect("file:user_credentials.db?mode=ro", uri=True)
cur = conn.cursor()

tables = cur.execute(
    "SELECT name FROM sqlite_master WHERE type IN ('table', 'view') ORDER BY name"
).fetchall()
print("Objects:", tables)

for (name,) in tables:
    print(f"\n--- schema for {name} ---")
    for row in cur.execute(f'SELECT sql FROM sqlite_master WHERE name = ?', (name,)):
        print(row[0])
    print(f"--- rows in {name} ---")
    try:
        for row in cur.execute(f"SELECT * FROM {name} LIMIT 20"):
            print(row)
    except sqlite3.Error as exc:
        print("could not read:", exc)

conn.close()

"""Task-local helper: inspect the workspace for SQLite databases and report their schema."""
import os
import sqlite3

HERE = os.path.dirname(os.path.abspath(__file__))

print("Files in workspace:", sorted(os.listdir(HERE)))

db_files = [
    name
    for name in os.listdir(HERE)
    if name.lower().endswith((".db", ".sqlite", ".sqlite3", ".db3"))
]

if not db_files:
    print("No SQLite database files found in the workspace.")
else:
    for name in db_files:
        path = os.path.join(HERE, name)
        print(f"\n=== Database: {name} ===")
        try:
            with sqlite3.connect(path) as conn:
                conn.row_factory = sqlite3.Row
                cur = conn.cursor()
                tables = cur.execute(
                    "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
                ).fetchall()
                print("Tables:", [t["name"] for t in tables])
                for t in tables:
                    tname = t["name"]
                    cols = cur.execute(f'PRAGMA table_info("{tname}")').fetchall()
                    print(f"\nTable '{tname}' columns:")
                    for c in cols:
                        print(
                            f"  {c['name']} {c['type']} notnull={c['notnull']} "
                            f"default={c['dflt_value']!r} pk={c['pk']}"
                        )
                    count = cur.execute(f'SELECT COUNT(*) AS n FROM "{tname}"').fetchone()
                    print(f"  row count: {count['n']}")
        except sqlite3.Error as exc:
            print(f"Error inspecting {name}: {exc}")

